import type { RequestHandler } from './$types';
import { db, aircraftPositions } from '$lib/server/db';
import { debugResponse, debugError, parsePagination } from '$lib/server/debug-helpers';
import { eq, gte, lte, and, asc, desc } from 'drizzle-orm';

export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();
  try {
    const { limit, offset } = parsePagination(url.searchParams);
    const conditions = [];

    const flightId = url.searchParams.get('flight_id');
    if (flightId) conditions.push(eq(aircraftPositions.flightId, parseInt(flightId, 10)));

    const from = url.searchParams.get('from');
    if (from) conditions.push(gte(aircraftPositions.positionTimestamp, new Date(from)));
    const to = url.searchParams.get('to');
    if (to) conditions.push(lte(aircraftPositions.positionTimestamp, new Date(to)));

    const sortOrder = url.searchParams.get('order') === 'asc' ? asc : desc;

    const rows = conditions.length > 0
      ? await db.select().from(aircraftPositions).where(and(...conditions)).orderBy(sortOrder(aircraftPositions.positionTimestamp)).limit(limit).offset(offset)
      : await db.select().from(aircraftPositions).orderBy(sortOrder(aircraftPositions.positionTimestamp)).limit(limit).offset(offset);

    return debugResponse(rows, performance.now() - t0);
  } catch (err) {
    console.error('[debug/positions]', err);
    return debugError('Query failed', 500);
  }
};

/**
 * Shared helpers for /api/debug/* endpoints.
 * Server-only — never imported client-side.
 */

/**
 * Structured JSON response with metadata.
 * Every debug endpoint wraps its data in this shape.
 */
export function debugResponse(
  rows: unknown[],
  queryMs: number,
): Response {
  return new Response(
    JSON.stringify({
      rows,
      count: rows.length,
      queryMs: Math.round(queryMs),
    }),
    {
      status: 200,
      headers: {
        'content-type': 'application/json',
        'cache-control': 'no-store',
      },
    },
  );
}

/**
 * Error response for client errors (bad params, auth failures).
 */
export function debugError(message: string, status = 400): Response {
  return new Response(
    JSON.stringify({ error: message }),
    {
      status,
      headers: {
        'content-type': 'application/json',
        'cache-control': 'no-store',
      },
    },
  );
}

/**
 * Parse and clamp pagination params from URL search params.
 * Returns { limit, offset } with enforced caps.
 */
export function parsePagination(
  searchParams: URLSearchParams,
  defaults: { defaultLimit?: number; maxLimit?: number } = {},
): { limit: number; offset: number } {
  const defaultLimit = defaults.defaultLimit ?? 100;
  const maxLimit = defaults.maxLimit ?? 1000;

  const rawLimit = parseInt(searchParams.get('limit') ?? '', 10);
  const limit = Math.min(
    Math.max(1, isNaN(rawLimit) ? defaultLimit : rawLimit),
    maxLimit,
  );
  const rawOffset = parseInt(searchParams.get('offset') ?? '', 10);
  const offset = Math.max(0, isNaN(rawOffset) ? 0 : rawOffset);

  return { limit, offset };
}

/** SQL commands allowed by the debug SQL endpoint */
const ALLOWED_COMMANDS = new Set(['SELECT', 'EXPLAIN', 'SHOW', 'DESCRIBE', 'WITH']);

/** Keywords that are blocked even inside otherwise-allowed statements */
const DANGEROUS_KEYWORDS = ['INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'TRUNCATE', 'CREATE'];

/**
 * Validate a SQL query string for the debug endpoint.
 * Returns { valid: true } or { valid: false, error: string }.
 */
export function validateSqlQuery(query: string): { valid: true } | { valid: false; error: string } {
  const firstToken = query.split(/\s+/)[0]?.toUpperCase() ?? '';
  if (!ALLOWED_COMMANDS.has(firstToken)) {
    return { valid: false, error: `Statement type "${firstToken}" not allowed. Only SELECT, EXPLAIN, SHOW, DESCRIBE, and WITH are permitted.` };
  }

  const upperQuery = query.toUpperCase();
  for (const keyword of DANGEROUS_KEYWORDS) {
    if (new RegExp(`\\b${keyword}\\b`).test(upperQuery)) {
      return { valid: false, error: `Dangerous keyword "${keyword}" detected in query. Only read-only statements are allowed.` };
    }
  }

  return { valid: true };
}

/**
 * Validate a Bearer token for the debug API.
 * Returns true if the Authorization header matches the expected token.
 */
export function validateDebugToken(
  authHeader: string | null,
  expectedToken: string | undefined,
): boolean {
  if (!expectedToken || !authHeader) return false;
  return authHeader === `Bearer ${expectedToken}`;
}

// Server-only database module — SvelteKit enforces $lib/server is never accessible client-side.
// Vite resolves @airways/database via alias in vite.config.ts → packages/database/index.ts.
// pg and drizzle-orm are marked as ssr.external so they're never bundled.

export { db, getDb, guernseyTodayStr, guernseyTomorrowStr, isTerminalStatus } from '@airways/database';
export {
  flights,
  flightTimes,
  flightNotes,
  flightStatusHistory,
  weatherData,
  historicalWeather,
  airportDaylight,
  scraperLogs,
  aircraftPositions,
  airports,
  pushSubscriptions,
  notificationWatermark,
} from '@airways/database/schema';

import { drizzle } from 'drizzle-orm/node-postgres';
import pg, { Pool } from 'pg';
import * as schema from './schema';

// Force TIMESTAMP WITHOUT TZ (oid 1114) to always be read as UTC regardless of
// the Node.js process timezone. Without this, pg uses the process TZ to interpret
// the raw value, so a dev machine running BST reads the same stored instant as
// 1 hour earlier than a UTC Docker container — causing systematic display drift.
pg.types.setTypeParser(1114, (val: string) => new Date(val + 'Z'));

// Re-export schema types and table objects — safe to import anywhere
export * from './schema';

// Export inferred types for all tables
export type User = typeof schema.users.$inferSelect;
export type NewUser = typeof schema.users.$inferInsert;

export type Session = typeof schema.sessions.$inferSelect;
export type NewSession = typeof schema.sessions.$inferInsert;

export type Flight = typeof schema.flights.$inferSelect;
export type NewFlight = typeof schema.flights.$inferInsert;

export type FlightTime = typeof schema.flightTimes.$inferSelect;
export type NewFlightTime = typeof schema.flightTimes.$inferInsert;

export type FlightNote = typeof schema.flightNotes.$inferSelect;
export type NewFlightNote = typeof schema.flightNotes.$inferInsert;

export type FlightStatusHistory = typeof schema.flightStatusHistory.$inferSelect;
export type NewFlightStatusHistory = typeof schema.flightStatusHistory.$inferInsert;

export type WeatherDatum = typeof schema.weatherData.$inferSelect;
export type NewWeatherDatum = typeof schema.weatherData.$inferInsert;

export type AirportDaylight = typeof schema.airportDaylight.$inferSelect;
export type NewAirportDaylight = typeof schema.airportDaylight.$inferInsert;

export type Airport = typeof schema.airports.$inferSelect;
export type NewAirport = typeof schema.airports.$inferInsert;

export type ScraperLog = typeof schema.scraperLogs.$inferSelect;
export type NewScraperLog = typeof schema.scraperLogs.$inferInsert;

export type AircraftPosition = typeof schema.aircraftPositions.$inferSelect;
export type NewAircraftPosition = typeof schema.aircraftPositions.$inferInsert;

export type PushSubscription = typeof schema.pushSubscriptions.$inferSelect;
export type NewPushSubscription = typeof schema.pushSubscriptions.$inferInsert;

export type HistoricalWeather = typeof schema.historicalWeather.$inferSelect;
export type NewHistoricalWeather = typeof schema.historicalWeather.$inferInsert;

export type NotificationWatermark = typeof schema.notificationWatermark.$inferSelect;
export type NewNotificationWatermark = typeof schema.notificationWatermark.$inferInsert;
export { tryAcquireServiceLock } from './singleton';
export {
  clearAllTimers,
  countFlightsForDate,
  getActiveFlightsToday,
  getEstimatedTimesBatch,
  msSinceLastScrape,
  logSchedulerEvent,
  computeNextInterval,
  shouldSleep,
  computeWakeTime,
  type TimerState,
} from './scheduler';
export { canUpgradeStatus, isTerminalStatus } from './statusPriority';
export { ROUTE_FLIGHT_MINUTES, LOCATION_TO_IATA, routeFlightMinutes, locationToIata } from './constants';
export { GY_TZ, localToUtc, guernseyTodayStr, guernseyTomorrowStr, guernseyHour, nextGuernseyTime, checkTimezoneOffset } from './time';
export type { TimezoneCheckResult } from './time';

export type DbClient = ReturnType<typeof drizzle<typeof schema>>;

let _db: DbClient | null = null;

export function getDb(): DbClient {
  if (_db) return _db;
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is not set');
  // Keep pool small per-service so 6 services don't exhaust PostgreSQL's
  // default max_connections (typically 100). Each service gets up to 5
  // connections; peak total = 30, leaving headroom for admin tools.
  const pool = new Pool({
    connectionString: url,
    max: 5,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: 5_000,
  });
  // Enforce UTC session timezone on every connection so that TIMESTAMP WITHOUT TZ
  // values written by pg are stored as UTC wall-clock, consistent with TZ=UTC containers.
  pool.on('connect', (client) => { client.query("SET TIME ZONE 'UTC'").catch(() => {}); });
  _db = drizzle(pool, { schema });
  return _db;
}

// Proxy-based `db` export — lazily initialises the pool on first use.
// Only import this from server-side code (*.server.ts / Node scrapers).
export const db: DbClient = new Proxy({} as DbClient, {
  get(_t, prop) {
    return (getDb() as unknown as Record<string | symbol, unknown>)[prop];
  },
  apply(_t, _this, args) {
    return (getDb() as unknown as (...a: unknown[]) => unknown)(...args);
  },
});

